using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Api.Authorization;using Dhole.Content.Api.Extensions;using Dhole.Content.Application.Settings.DeleteSiteSetting;using Dhole.Content.Application.Settings.GetSiteSettings;using Dhole.Content.Application.Settings.UpsertSiteSetting;using Dhole.Content.Contracts.Settings;namespace Dhole.Content.Api.Endpoints;public static class SiteSettingEndpoints{public static IEndpointRouteBuilder MapSiteSettingEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/settings").WithTags("Content Settings").RequireAuthorization();g.MapGet("/",async(string? siteKey,IQueryDispatcher d,CancellationToken ct)=>EndpointResults.Ok(await d.DispatchAsync(new GetSiteSettingsQuery(siteKey??"main",false),ct))).RequireScope(ContentScopeNames.View);g.MapPut("/{key}",async(string key,UpsertSiteSettingRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new UpsertSiteSettingCommand(key,r.ValueJson,r.IsPublic,r.SiteKey,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.SettingsEdit);g.MapDelete("/{id:guid}",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new DeleteSiteSettingCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.SettingsEdit);return app;}}
